// Binomial Coefficient (C(n,r)) {{{
#[derive(Debug,Clone)]
struct Cnr {
	n: usize,
	pub f: Box<[Field]>,
	fi: Box<[Field]>
}
#[allow(dead_code)]
impl Cnr {
	fn new(n: usize) -> Self {
		let mut f = Vec::with_capacity(n+1);
		f.push(Z1);
		for i in 1..=n {
			f.push(f[i-1] * Field::new(i as i32));
		}
		let mut fi = vec![Z1; n+1];
		fi[n] = f[n].inv();
		for i in (0..n).rev() {
			fi[i] = fi[i+1] * Field::new(i as i32 + 1);
		}
		let f = f.into_boxed_slice();
		let fi = fi.into_boxed_slice();
		Self {n, f, fi}
	}
	fn cnr(&self, n: usize, r: usize) -> Field {
		if r > n {
			Z0
		} else {
			self.f[n] * self.fi[r] * self.fi[n-r]
		}
	}
}//}}}

fn main() {
	let mut rin = reader();
	let mut rout = writer();

	l!(n,x,p = rin.u());
	let x = x-1;
	let mut lo = 0;
	let mut hi = n;
	l!(mut lo_fix,hi_fix = 0);
	while lo < hi {
		let mid = (lo + hi) / 2;
		if mid == p {
			lo = mid + 1;
		} else if mid < p {
			lo_fix += 1;
			lo = mid + 1;
		} else {
			hi_fix += 1;
			hi = mid;
		}
	}

	let f = Cnr::new(n);
	let sol = f.cnr(x, lo_fix) * f.f[lo_fix] * f.cnr(n-1-x, hi_fix) * f.f[hi_fix] * f.f[n - hi_fix - lo_fix - 1];
	writeln!(rout, "{}", sol).ok();
}
